18	constexpr u64 RS_MAX_DATA_SIZE = 16 * 1024 * 1024;
19	constexpr u64 AR_ONESHOT_1D_MAX_DATA_SIZE = 16 * 1024;
20	constexpr u64 AR_M2M_1D_MAX_DATA_SIZE = 8 * 1024 * 1024;
