473	SelectorStatus AllReduceAutoSelector::SelectMeshAlgoAicpuUBX(
474	    const TopoInfoWithNetLayerDetails* topoInfo, const u64 dataSize, std::string& selectAlgName,
475	    bool isDataTypeOrReduceTypeSpecial) const
476	{
477	    // UBX机型
478	    bool isMeshNumEqualToClosNum = false;
479	    bool isClosNumMultipleOfMeshNum = false;
480	    CHK_PRT_RET(
481	        CheckMeshNumEqualToClosNum(topoInfo, isMeshNumEqualToClosNum) != HCCL_SUCCESS,
482	        HCCL_ERROR("[Algo][AllReduceAutoSelector] CheckMeshNumEqualToClosNum failed."), SelectorStatus::NOT_MATCH);
483	    CHK_PRT_RET(
484	        CheckClosNumMultipleOfMeshNum(topoInfo, isClosNumMultipleOfMeshNum) != HCCL_SUCCESS,
485	        HCCL_ERROR("[Algo][AllReduceAutoSelector] CheckClosNumMultipleOfMeshNum failed."), SelectorStatus::NOT_MATCH);
486	    if (isMeshNumEqualToClosNum && topoInfo->userRankSize <= MAX_RANK_NUM_FOR_CONCURRENT_ALGO) {
487	        if (isDataTypeOrReduceTypeSpecial) {
488	            selectAlgName = dataSize <= AR_AICPU_1D_64DATATYPE_DATA_SIZE ? "AicpuAllReduceSoleMeshOneShot" :
489	                                                                           "AicpuAllReduceSoleMeshTwoShot";
490	        } else if (dataSize <= AR_AICPU_1D_SMALL_DATA_SIZE) {
491	            selectAlgName = "AicpuAllReduceSoleMeshOneShot";
492	        } else {
493	            // 大数据量，用mesh+clos并行算法
494	            selectAlgName = "AicpuAllReduceConcurMeshTwoShotNHR";
495	        }
496	    } else if (isDataTypeOrReduceTypeSpecial) {
497	        selectAlgName = "AicpuAllReduceSoleNHRAicpuReduce";
498	    } else if (isClosNumMultipleOfMeshNum && !IsSmallData(dataSize)) {
499	        // 矩形场景大数据量，用Parallel并行算法
500	        selectAlgName = "InsAllReduceParallelRSAGUBX";
501	    } else {
502	        // 其他场景，用1d NHR算法
503	        selectAlgName = "AicpuAllReduceSoleNHR";
504	    }
505	
506	    HCCL_DEBUG("[AllReduceAutoSelector][%s] Algo match [%s]", __func__, selectAlgName.c_str());
507	    return SelectorStatus::MATCH;
508	}
